export interface BusinessInfo {
  industry: string;
  specialty: string;
  address: string;
  website: string;
  facebook: string;
  zalo: string;
}

export interface SEOResult {
  htmlContent: string;
  metadata: {
    title: string;
    description: string;
    keywords: string;
  };
}

export enum AppStep {
  BUSINESS_INFO = 'BUSINESS_INFO',
  CONTENT_INPUT = 'CONTENT_INPUT',
  GENERATING = 'GENERATING',
  RESULT = 'RESULT'
}

import { GoogleGenAI, Type } from "@google/genai";
import { BusinessInfo, SEOResult } from "../types";

export const generateSEOContent = async (
  business: BusinessInfo,
  topic: string
): Promise<SEOResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  // System instruction to guide the AI on tone and context
  const systemInstruction = `Bạn là một chuyên gia Marketing và Chuyên gia SEO google hàng đầu. 
Nhiệm vụ của bạn là viết bài Content chuẩn SEO chuyên sâu, văn phong dễ hiểu, gần gũi.
Bạn phải giải quyết nỗi lo của khách hàng về việc viết bài SEO lên TOP Google.

Thông tin doanh nghiệp:
- Ngành nghề: ${business.industry}
- Chuyên môn: ${business.specialty}
- Địa chỉ: ${business.address}
- Website: ${business.website}
- Facebook: ${business.facebook}
- Zalo: ${business.zalo}

Yêu cầu định dạng đầu ra cực kỳ nghiêm ngặt:
1. Trả về nội dung HTML hoàn chỉnh với inline CSS như mẫu yêu cầu.
2. Sau phần HTML, cung cấp phần SEO METADATA bao gồm: SEO Title, SEO Description, và SEO Keywords.
`;

  const prompt = `Hãy giúp tôi viết 1 bài Content chuẩn SEO google cho chủ đề: [${topic}].

Yêu cầu phần mở đầu hấp dẫn, thu hút sự chú ý ngay lập tức.
Nội dung content phải đạt được 14 tiêu chí sau:
1. Bôi đen Từ khóa tập trung cho nội dung này.
2. Sử dụng từ khóa chính gần đầu tiêu đề SEO.
3. Tiêu đề SEO phải ngắn gọn và chứa từ khóa.
4. Sử dụng từ khóa chính trong URL (Slug). Bôi đen mục này ở đầu content.
5. URL tối ưu 21 ký tự.
6. Sử dụng từ khóa chính ở ngay đoạn đầu nội dung.
7. Phân bổ từ khóa chính xuyên suốt nội dung.
8. Nội dung phải cực kỳ chi tiết, dài trên 3000 từ (QUAN TRỌNG).
9. Thêm liên kết nội bộ giả định vào nội dung.
10. Sử dụng từ khóa chính trong các thẻ tiêu đề H2, H3, H4 (không ghi chữ H2, H3 vào text).
11. Chèn các vị trí Chú thích ảnh thông minh [Chú thích ảnh: ...] kèm gợi ý nội dung ảnh.
12. Sử dụng các đoạn văn ngắn, súc tích, dễ đọc.
13. Từ khóa chính lặp lại trong nội dung ít nhất 6 lần.
14. Thêm một phần "Đoạn trích nổi bật" (Featured Snippet) súc tích.

Lưu ý quan trọng:
- Không sử dụng bất kỳ ICON nào.
- Không dùng số thứ tự đầu câu nếu không cần thiết.
- Viết như một chuyên gia SEO thực thụ.
- Sử dụng font Verdana, Geneva, sans-serif và cỡ chữ 16px-18px trong style HTML.
- Sử dụng các blockquote và bảng so sánh nếu cần thiết để tăng UX.

Cuối cùng hãy gửi riêng Metadata SEO:
SEO Title: [Nội dung]
SEO Description: [Nội dung]
SEO Keywords: [Nội dung]
`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      systemInstruction,
      thinkingConfig: { thinkingBudget: 16000 },
      maxOutputTokens: 8192 // Ensure enough space for 3000+ words
    },
  });

  const rawText = response.text;

  // Parsing logic to separate HTML and Metadata
  // We expect a structure where HTML is first and Metadata is tagged at the end
  const metadataMatch = rawText.match(/SEO Title:([\s\S]*?)SEO Description:([\s\S]*?)SEO Keywords:([\s\S]*?)$/i);

  let htmlPart = rawText;
  let metadata = {
    title: 'N/A',
    description: 'N/A',
    keywords: 'N/A'
  };

  if (metadataMatch) {
    htmlPart = rawText.split(/SEO Title/i)[0].trim();
    metadata = {
      title: metadataMatch[1].trim(),
      description: metadataMatch[2].trim(),
      keywords: metadataMatch[3].trim()
    };
  }

  return {
    htmlContent: htmlPart,
    metadata
  };
};

import React, { useState, useCallback } from 'react';
import { BusinessInfo, SEOResult, AppStep } from './types';
import Header from './components/Header';
import BusinessForm from './components/BusinessForm';
