import React, { useState } from 'react';
import { BusinessInfo, SEOResult } from '../types';
import { generateSEOContent } from '../services/geminiService';

interface SEOContentGeneratorProps {
  businessInfo: BusinessInfo;
  onStart: () => void;
  onComplete: (result: SEOResult) => void;
}

const SEOContentGenerator: React.FC<SEOContentGeneratorProps> = ({ 
  businessInfo, 
  onStart,
  onComplete 
}) => {
  const [topic, setTopic] = useState('');
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!topic.trim()) {
      alert("Vui lòng nhập từ khóa hoặc tiêu đề bài viết.");
      return;
    }

    setError(null);
    onStart();

    try {
      const result = await generateSEOContent(businessInfo, topic);
      onComplete(result);
    } catch (err: any) {
      console.error(err);
      setError("Có lỗi xảy ra trong quá trình tạo nội dung. Vui lòng thử lại.");
      // If error occurs, we should technically provide a way to go back or retry
    }
  };

  return (
    <div className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
      <div className="mb-6">
        <div className="inline-flex items-center px-3 py-1 bg-green-100 text-green-700 text-xs font-bold rounded-full mb-4">
          ✓ ĐÃ HỌC THÔNG TIN DOANH NGHIỆP
        </div>
        <h2 className="text-2xl font-bold text-gray-800">Bước 2: Nhập Từ khóa / Tiêu đề</h2>
        <p className="text-gray-500 mt-2">AI sẽ dựa trên chuyên môn của bạn để viết bài Content chuẩn SEO dài 3000 từ.</p>
      </div>

      <div className="space-y-4">
        <div className="p-4 bg-gray-50 rounded-xl border border-dashed border-gray-300">
          <p className="text-xs text-gray-500 font-medium mb-1 uppercase tracking-wider">Tóm tắt hồ sơ:</p>
          <div className="text-sm text-gray-700">
            <span className="font-semibold">{businessInfo.industry}</span> - {businessInfo.specialty}
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-sm font-semibold text-gray-700 block">Chủ đề chính bài viết <span className="text-red-500">*</span></label>
          <input 
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="VD: Cách độ màn hình Android cho Vinfast VF3 tiết kiệm nhất"
            className="w-full px-4 py-4 rounded-xl border border-gray-200 focus:border-blue-500 focus:ring-2 focus:ring-blue-200 transition-all outline-none text-lg font-medium"
          />
        </div>

        {error && (
          <div className="p-4 bg-red-50 text-red-600 rounded-xl text-sm border border-red-100">
            {error}
          </div>
        )}

        <button 
          onClick={handleGenerate}
          className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-bold py-5 rounded-xl shadow-xl shadow-blue-100 transition-all transform hover:-translate-y-1 flex items-center justify-center space-x-2"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
          </svg>
          <span>BẮT ĐẦU VIẾT BÀI 3000 TỪ (AI AUTO)</span>
        </button>
      </div>
    </div>
  );
};

export default SEOContentGenerator;

import React, { useState } from 'react';
import { SEOResult } from '../types';

interface ResultDisplayProps {
  result: SEOResult;
  onReset: () => void;
}

const ResultDisplay: React.FC<ResultDisplayProps> = ({ result, onReset }) => {
  const [activeTab, setActiveTab] = useState<'preview' | 'html' | 'metadata'>('preview');
  const [copied, setCopied] = useState(false);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="bg-white rounded-2xl shadow-xl border border-gray-100 overflow-hidden">
        <div className="border-b px-4 py-2 bg-gray-50 flex flex-wrap gap-2">
          <button 
            onClick={() => setActiveTab('preview')}
            className={`px-4 py-2 text-sm font-semibold rounded-lg transition-all ${activeTab === 'preview' ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
          >
            Xem trước
          </button>
          <button 
            onClick={() => setActiveTab('html')}
            className={`px-4 py-2 text-sm font-semibold rounded-lg transition-all ${activeTab === 'html' ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
          >
            Mã HTML
          </button>
          <button 
            onClick={() => setActiveTab('metadata')}
            className={`px-4 py-2 text-sm font-semibold rounded-lg transition-all ${activeTab === 'metadata' ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
          >
            SEO Metadata
          </button>

          <div className="ml-auto flex items-center">
             <button 
              onClick={() => handleCopy(activeTab === 'html' ? result.htmlContent : (activeTab === 'metadata' ? JSON.stringify(result.metadata, null, 2) : result.htmlContent))}
              className="flex items-center space-x-1 px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg text-xs font-bold hover:bg-blue-100 transition-all"
            >
              {copied ? '✓ Đã chép' : '⧉ Sao chép'}
            </button>
          </div>
        </div>

        <div className="p-6 max-h-[70vh] overflow-y-auto">
          {activeTab === 'preview' && (
            <div 
              className="prose max-w-none prose-blue" 
              dangerouslySetInnerHTML={{ __html: result.htmlContent }} 
            />
          )}

          {activeTab === 'html' && (
            <pre className="bg-gray-900 text-gray-100 p-6 rounded-xl text-sm font-mono whitespace-pre-wrap break-all">
              {result.htmlContent}
            </pre>
          )}

          {activeTab === 'metadata' && (
            <div className="space-y-6">
              <div className="p-4 bg-blue-50 rounded-xl border border-blue-100">
                <h3 className="text-xs font-bold text-blue-400 uppercase tracking-widest mb-2">SEO Title</h3>
                <p className="text-gray-800 font-semibold text-lg">{result.metadata.title}</p>
              </div>
              <div className="p-4 bg-blue-50 rounded-xl border border-blue-100">
                <h3 className="text-xs font-bold text-blue-400 uppercase tracking-widest mb-2">SEO Description</h3>
                <p className="text-gray-700 leading-relaxed">{result.metadata.description}</p>
              </div>
              <div className="p-4 bg-blue-50 rounded-xl border border-blue-100">
                <h3 className="text-xs font-bold text-blue-400 uppercase tracking-widest mb-2">SEO Keywords</h3>
                <p className="text-gray-700">{result.metadata.keywords}</p>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="flex justify-between items-center">
        <button 
          onClick={onReset}
          className="px-6 py-3 bg-gray-100 hover:bg-gray-200 text-gray-600 font-bold rounded-xl transition-all"
        >
          ← Viết bài mới
        </button>
        <p className="text-sm text-gray-400 italic">Lưu ý: Bạn có thể copy mã HTML dán trực tiếp vào trình soạn thảo bài viết của Website.</p>
      </div>
    </div>
  );
};

